#!/usr/bin/env bash
# {{script_name}}.sh, generated by API Toolbar on {{date}}.
# @if hosts
# Calls: {{hosts}}
# @end
#
# Run with: bash {{script_name}}.sh
# Responses are saved to OUT_DIR, one file per request.

set -euo pipefail
umask 077
# Stops Git Bash on Windows rewriting arguments that look like file paths.
export MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'

for tool in {{tools}}; do
  if ! command -v "$tool" > /dev/null; then
    echo "This script needs $tool. To get jq: winget install jqlang.jq (Windows), brew install jq (macOS), apt install jq (Linux)." >&2
    exit 1
  fi
done

ENV_FILE="$(dirname "${BASH_SOURCE[0]}")/$(basename "${BASH_SOURCE[0]}" .sh).env"
if [[ -f $ENV_FILE ]]; then
  set -a
  . "$ENV_FILE"
  set +a
fi

OUT_DIR="${OUT_DIR:-./{{script_name}}_output}"
# @if has_loops
# Safety limits for loops, and a pause between requests to stay polite.
MAX_PAGES="${MAX_PAGES:-100}"
MAX_ITEMS="${MAX_ITEMS:-1000}"
DELAY="${DELAY:-0.2}"
# @end

{{settings}}

mkdir -p "$OUT_DIR/headers"
JAR="$OUT_DIR/cookies.txt"
: > "$JAR"

die() {
  echo "Error: $*" >&2
  exit 1
}

# request <file> <method> <url> [curl options]
# Sets RESP to the saved body and RESP_HEADERS to the saved headers.
request() {
  local file=$1 method=$2 url=$3 status
  shift 3
  RESP="$OUT_DIR/$file"
  RESP_HEADERS="$OUT_DIR/headers/$file.txt"
  : > "$RESP"
  if [[ $method == GET ]]; then set -- --retry 3 --retry-delay 1 "$@"; fi
  if [[ $method == HEAD ]]; then set -- -I "$@"; else set -- -X "$method" "$@"; fi
  status=$(curl -sS --compressed --connect-timeout 15 -o "$RESP" -D "$RESP_HEADERS" \
    -w '%{http_code}' -b "$JAR" -c "$JAR" "$@" "$url")
  echo "$method $file: HTTP $status" >&2
  if (( status >= 400 )) && [[ -z ${ALLOW_ERROR:-} ]]; then
    head -c 500 "$RESP" >&2
    echo >&2
    die "$file failed with HTTP $status"
  fi
}

# @helper jget
# jget <file> <jq filter>: read one value, or stop if the response changed.
jget() {
  local value
  value=$(jq -r "$2" "$1" | tr -d '\r')
  if [[ -z $value || $value == null ]]; then die "No value at $2 in $1"; fi
  printf '%s' "$value"
}

# @end
# @helper header_value
# header_value <header file> <name>: read one response header, if present.
header_value() {
  { grep -i "^$2:" "$1" || true; } | tail -n 1 | cut -d: -f2- | sed 's/^ *//' | tr -d '\r'
}

# @end
# @helper hget
# hget <header file> <name>: read a header the script cannot do without.
hget() {
  local value
  value=$(header_value "$1" "$2")
  if [[ -z $value ]]; then die "No $2 header in $1"; fi
  printf '%s' "$value"
}

# @end
# @helper jar_get
# jar_get <name>: read a cookie the server set during this run.
jar_get() {
  local value
  value=$(awk -F '\t' -v name="$1" 'NF >= 7 && $6 == name { value = $7 } END { print value }' "$JAR" | tr -d '\r')
  if [[ -z $value ]]; then die "No cookie named $1 in $JAR"; fi
  printf '%s' "$value"
}

# @end
# @helper between
# between <file> <text before> <text after>: cut a value out of a page.
between() {
  local text
  text=$(<"$1")
  if [[ $text != *"$2"* ]]; then die "Could not find '$2' in $1"; fi
  text=${text#*"$2"}
  printf '%s' "${text%%"$3"*}"
}

# @end
# @helper urlencode
urlencode() { jq -rn --arg value "$1" '$value | @uri' | tr -d '\r'; }

# @end
# @helper urldecode
urldecode() { local text=${1//+/ }; printf '%b' "${text//%/\\x}"; }

# @end
# @helper url_param
# url_param <url> <name>: read one query parameter from a URL.
url_param() {
  local query=${1#*\?} pair
  query=${query%%#*}
  while IFS= read -r -d '&' pair; do
    if [[ $pair == "$2="* ]]; then printf '%s' "${pair#*=}"; return; fi
  done <<< "$query&"
}

# @end
# @helper json_set
# json_set <json> <jq filter> [jq args]: fill values into a request body.
json_set() {
  local json=$1 filter=$2
  shift 2
  jq -ac "$@" "$filter" <<< "$json" | tr -d '\r'
}

# @end
# @helper seed_cookies
# seed_cookies <host> <"a=1; b=2">: start the jar with cookies from the browser.
seed_cookies() {
  local rest="$2; " pair
  while [[ $rest == *"; "* ]]; do
    pair=${rest%%"; "*}
    rest=${rest#*"; "}
    printf '%s\tFALSE\t/\tFALSE\t0\t%s\t%s\n' "$1" "${pair%%=*}" "${pair#*=}" >> "$JAR"
  done
}

# @end
# @helper collect
# collect <response> <jq filter> <output file>: append records as JSON lines.
collect() { jq -c "$2" "$1" | tr -d '\r' >> "$3"; }

# @end
{{seed_cookies}}

{{steps}}

echo "Done. Responses are in $OUT_DIR" >&2
# @snippet request
{{before}}
{{error_prefix}}request {{file}} {{method}} {{url}}{{options}}
# @end
# @snippet extract
{{var}}=$({{value}})
# @end
# @snippet counter_loop
{{var}}={{start}}
: > {{output}}
for (( pass = 1; pass <= {{limit}}; pass++ )); do
  {{request}}
# @if has_items
  count=$(jq {{count_filter}} "$RESP" | tr -d '\r')
  if (( count == 0 )); then break; fi
  collect "$RESP" {{items_filter}} {{output}}
# @end
  {{var}}=$(( {{var}} + {{step}} ))
  sleep "$DELAY"
done
# @end
# @snippet cursor_loop
{{var}}={{initial}}
: > {{output}}
for (( pass = 1; pass <= MAX_PAGES; pass++ )); do
# @if has_extra_query
  URL={{base_url}}
  if [[ -n ${{var}} ]]; then URL+={{extra_query}}; fi
# @end
  {{request}}
# @if has_items
  collect "$RESP" {{items_filter}} {{output}}
# @end
  {{var}}=$({{next_value}})
  if [[ -z ${{var}} ]]; then break; fi
  sleep "$DELAY"
done
# @end
# @snippet next_url_loop
URL={{first_url}}
: > {{output}}
for (( pass = 1; pass <= MAX_PAGES; pass++ )); do
  {{request}}
# @if has_items
  collect "$RESP" {{items_filter}} {{output}}
# @end
  NEXT=$({{next_value}})
  if [[ -z $NEXT ]]; then break; fi
  URL={{next_url}}
  sleep "$DELAY"
done
# @end
# @snippet foreach_loop
: > {{output}}
pass=0
while IFS= read -r {{var}}; do
  pass=$(( pass + 1 ))
  {{request}}
# @if is_json
  collect "$RESP" '.' {{output}}
# @end
  sleep "$DELAY"
done < <({{values}})
# @end
